            world.AddChild(wall); // TEST-SUPPORT: SHIELD-RECOVERY-013 | Tests: sMPGWM.Tests.ShieldColliderGeometryTests.StationaryShieldRecoveryMovesOutOfWall
            ship.Runtime.ApplyEquipment(new(0, 0, 0, 0, 0, 1, 0, 100, 1000, 0, 100, 0, 0, false, false, true, true, false), 0); // TEST-SUPPORT: SHIELD-RECOVERY-014 | Tests: sMPGWM.Tests.ShieldColliderGeometryTests.StationaryShieldRecoveryMovesOutOfWall
